<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
require_once DOGOFLOW_ROOT . '/core/catalog/ProductImages.php';
require_once DOGOFLOW_ROOT . '/core/catalog/StoreArt.php';
$slug=trim((string)($_GET['slug']??'')); if($slug===''){http_response_code(404);exit('Store not found.');}
$stmt=db()->prepare("SELECT sp.*,u.id seller_id FROM seller_profiles sp JOIN users u ON u.id=sp.user_id WHERE u.role='seller' AND u.status='active' AND sp.status='active' AND sp.approval_status='approved' AND (sp.store_slug=:slug_exact OR (sp.store_slug IS NULL AND LOWER(REPLACE(sp.business_name,' ','-'))=:slug_fallback)) LIMIT 1");
$stmt->execute(['slug_exact'=>$slug,'slug_fallback'=>$slug]); $store=$stmt->fetch(PDO::FETCH_ASSOC); if(!$store){http_response_code(404);exit('Store not found.');}
$stmt=db()->prepare("SELECT p.*, COALESCE((SELECT pi.image_path FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.is_primary DESC, pi.sort_order ASC, pi.id ASC LIMIT 1), p.image) AS gallery_image FROM products p WHERE p.seller_id=:sid AND p.status='active' ORDER BY p.created_at DESC LIMIT 48");$stmt->execute(['sid'=>(int)$store['seller_id']]);$products=$stmt->fetchAll(PDO::FETCH_ASSOC);
$title=$store['business_name'].' | DogoFlow';$desc=$store['store_description']?:'Shop products from '.$store['business_name'].' on DogoFlow.';$logo=trim((string)($store['store_logo']??''));$banner=trim((string)($store['store_banner']??''));$img=$banner?:($logo?:url('/assets/images/og/dogoflow-og.png'));if(strpos($img,'http')!==0)$img=url('/'.ltrim($img,'/'));
?>
<!doctype html><html lang="en"><head><link rel="icon" href="<?= e(url('/assets/images/favicon-32.png')) ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e(url('/store.php?slug='.urlencode($slug)))?>"><meta property="og:type" content="website"><meta property="og:title" content="<?=e($title)?>"><meta property="og:description" content="<?=e($desc)?>"><meta property="og:url" content="<?=e(url('/store.php?slug='.urlencode($slug)))?>"><meta property="og:image" content="<?=e($img)?>"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="<?=e($title)?>"><meta name="twitter:description" content="<?=e($desc)?>"><meta name="twitter:image" content="<?=e($img)?>"><?php require __DIR__ . '/partials/tailwind.php'; ?><style>
