n:none;color:var(--navy);transition:.2s}.sf3-product:hover{transform:translateY(-3px);box-shadow:0 14px 35px #0a162812}.sf3-product-image{aspect-ratio:1/1;background:var(--soft);display:block}.sf3-product-image img{width:100%;height:100%;object-fit:contain}.sf3-product-body{padding:13px}.sf3-product h3{font-size:.9rem;line-height:1.3;margin:0 0 6px}.sf3-price{color:var(--blue);font-weight:900;font-size:.95rem}.sf3-empty{padding:45px;border:1px dashed #cbd5e1;border-radius:18px;color:var(--muted)}@media(max-width:900px){.sf3-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.sf3-links a:not(.sf3-login):not(:nth-child(1)):not(:nth-child(2)){display:none}.sf3-banner{height:175px}.sf3-profile{align-items:flex-start;flex-wrap:wrap;padding:0 16px 18px}.sf3-share{margin-left:0}.sf3-grid{grid-template-columns:repeat(2,1fr)}.sf3-main{padding-top:12px}}
