@media(max-width:640px){.df3-links .df3-join{display:none}.df3-hero{padding:30px 0 18px}.df3-hero-row{align-items:start;flex-direction:column;gap:12px}.df3-count{min-width:0;padding:8px 12px}.df3-count strong{font-size:1.05rem}.df3-count span{display:inline;margin-left:5px}.df3-grid{grid-template-columns:1fr 1fr;gap:10px}.df3-card .df3-view{font-size:.7rem}.df3-body{padding:10px}.df3 .wrap{width:min(100% - 22px,1180px)}}</style></head><body class="sf3"><header class="df3-nav"><div class="wrap"><a class="df3-brand" href="<?= e(url('/')) ?>"><img src="<?= e(url('/assets/images/df-logo.png')) ?>" alt="DogoFlow"></a><nav class="df3-links"><a href="<?= e(url('/products.php')) ?>">Products</a><a href="<?= e(url('/stores.php')) ?>">Stores</a><a href="<?= e(url('/auth/login.php')) ?>" class="df3-login">Login</a><a class="df3-join" href="<?= e(url('/auth/register.php')) ?>">Create account</a></nav></div></header><main class="wrap sf3-main"><section class="sf3-hero"><div class="sf3-banner"><?php if($banner!==''): ?><img src="<?=e(url('/'.ltrim($banner,'/')))?>" alt="<?=e($store['business_name'])?> cover"><?php else: ?><img src="<?=e(StoreArt::cover($slug.'|'.(string)($store['seller_code']??''), (string)$store['business_name']))?>" alt=""><?php endif; ?></div><div class="sf3-profile"><?php if($logo!==''): ?><img class="sf3-logo" src="<?=e(url('/'.ltrim($logo,'/')))?>" alt="<?=e($store['business_name'])?> logo"><?php else: ?><img class="sf3-logo" src="<?=e(StoreArt::avatar($slug.'|'.(string)($store['seller_code']??''), (string)$store['business_name']))?>" alt=""><?php endif; ?><div><h1><?=e($store['business_name'])?></h1><p><?=e($desc)?></p><p><?=e((string)($store['store_location']??''))?><?php if(!empty($store['business_phone'])): ?> · <?=e($store['business_phone'])?><?php endif; ?></p></div><button class="sf3-share" type="button" onclick="navigator.clipboard&&navigator.clipboard.writeText(window.location.href).then(()=>this.textContent='Link copied!')">Share store</button></div></section><div class="sf3-heading"><div><h2>Shop this store</h2><span>Products from <?=e($store['business_name'])?></span></div><span><?=count($products)?> products</span></div><div class="sf3-grid"><?php foreach($products as $p): $pimg=trim((string)($p['gallery_image']??$p['image']??'')); ?><a class="sf3-product" href="<?=e(url('/product.php?id='.(int)$p['id']))?>"><span class="sf3-product-image"><?php if($pimg!==''): ?><img src="<?=e(url('/'.ltrim($pimg,'/')))?>" alt="<?=e($p['name'])?>" loading="lazy"><?php else: ?><img src="<?=e(url('/assets/images/product-placeholder.png'))?>" alt="" loading="lazy"><?php endif; ?></span><div class="sf3-product-body"><h3><?=e($p['name'])?></h3><span class="sf3-price">GH₵ <?=e(number_format((float)$p['price'],2))?></span></div></a><?php endforeach; ?><?php if(!$products): ?><div class="sf3-empty">This store has no published products yet.</div><?php endif; ?></div></main><?php require __DIR__.'/includes/footer.php'; ?></body></html>